export const ZAddGuestsInputSchema = z.object({
  bookingId: z.number(),
  guests: z.array(z.string().email()).transform((guests) => Array.from(new Set(guests))),
});

const seenGuestEmails = new Set(booking.attendees.map((attendee) => attendee.email.toLowerCase()));
const uniqueGuests = guests.filter((guest) => {
  const normalizedEmail = guest.toLowerCase();
  if (seenGuestEmails.has(normalizedEmail) || blacklistedGuestEmails.includes(normalizedEmail)) {
    return false;
  }
  seenGuestEmails.add(normalizedEmail);
  return true;
});

const blacklistedGuestEmails = process.env.BLACKLISTED_GUEST_EMAILS
  ? process.env.BLACKLISTED_GUEST_EMAILS.split(",").map((email) => email.toLowerCase())
  : [];

const normalizeGuestEmail = (email: string): string => {
  const [localPart, domain] = email.split("@");
  return `${localPart.split("+")[0]}@${domain}`.toLowerCase();
};

const uniqueGuests = guests.filter(
